package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

var _ = decimal.NewFromInt

type PartRec struct {
	LbPart   string
	LbRegion string
	LbSerial int64
}

var WsEofFlag string = "N"
var WsLabel string = "                    "
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

var inputDone bool = false
var partFile *os.File
var partReader *bufio.Scanner
var partRec PartRec
var eofReached bool

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func delimitedBySpace(s string) string {
	if idx := strings.IndexByte(s, ' '); idx >= 0 {
		return s[:idx]
	}
	return s
}

func formatPIC9(n int64, width int) string {
	s := fmt.Sprintf("%d", n)
	if len(s) > width {
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func MAIN_PARA() {
	OPEN_INPUT()
	READ_PARA()
	for !inputDone {
		PROCESS_PARA()
	}
	CLOSE_FILE()
	SUMMARY_PARA()
}

func OPEN_INPUT() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty
		eofReached = true
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	partFile = f
	partReader = bufio.NewScanner(f)
	// allow long lines
}

func CLOSE_FILE() {
	if partFile != nil {
		partFile.Close()
	}
}

func READ_PARA() {
	if eofReached {
		inputDone = true
		WsEofFlag = "Y"
		return
	}
	if partReader == nil {
		inputDone = true
		WsEofFlag = "Y"
		eofReached = true
		return
	}
	if !partReader.Scan() {
		inputDone = true
		WsEofFlag = "Y"
		eofReached = true
		return
	}
	line := partReader.Text()
	// LINE SEQUENTIAL: line without newline; pad with spaces on right if shorter than record length
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	// parse
	rawPart := line[0:8]
	rawRegion := line[8:11]
	rawSerial := line[11:15]

	var serialVal int64
	// rawSerial is digits, may contain spaces? Trim and parse
	trimmed := strings.TrimSpace(rawSerial)
	if trimmed == "" {
		serialVal = 0
	} else {
		// parse digits only
		var v int64
		for _, c := range trimmed {
			if c >= '0' && c <= '9' {
				v = v*10 + int64(c-'0')
			}
		}
		serialVal = v
		// But need to handle leading zeros: the above works. For "0000" -> 0
	}

	partRec = PartRec{
		LbPart:   rawPart,
		LbRegion: rawRegion,
		LbSerial: serialVal,
	}
	// Keep formatted serial for STRING: we need 4-digit zero pad later, so storing int is fine
	_ = rawSerial
}

func PROCESS_PARA() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0

	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	cnt := int64(strings.Count(partRec.LbPart, "A"))
	WsACount = cnt

	// STRING LB-REGION DELIMITED BY SPACE "-" DELIMITED BY SIZE LB-PART DELIMITED BY SPACE "-" DELIMITED BY SIZE LB-SERIAL DELIMITED BY SIZE INTO WS-LABEL
	partRegion := delimitedBySpace(partRec.LbRegion)
	partPart := delimitedBySpace(partRec.LbPart)
	serialStr := formatPIC9(partRec.LbSerial, 4)

	combined := partRegion + "-" + partPart + "-" + serialStr
	// INTO WS-LABEL: fill from start, remainder stays spaces, truncate if exceeds 20
	if len(combined) > 20 {
		combined = combined[:20]
		WsLabel = combined
	} else {
		WsLabel = combined + strings.Repeat(" ", 20-len(combined))
	}

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA += WsACount
	WsCount += 1

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL PIC X(20) exactly 20 chars
	// WS-A-COUNT PIC 99 zero-padded 2
	aCountStr := formatPIC9(WsACount, 2)
	fmt.Printf("%s A=%s\n", WsLabel, aCountStr)

	READ_PARA()
}

func SUMMARY_PARA() {
	countStr := formatPIC9(WsCount, 3)
	totalStr := formatPIC9(WsTotalA, 3)
	fmt.Printf("LABELS: %s A-TOTAL: %s\n", countStr, totalStr)
}

func main() {
	MAIN_PARA()
	if err := partReader.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}
